<template>
  <section class="admin-container"><header class="admin-header"><div><p class="eyebrow">CONTROL ROOM / ADMIN</p><h1>Quản trị <em>LuNu.</em></h1><p>Quản lý kho nhạc Cloudinary, nội dung Supabase và quyền truy cập của thành viên.</p></div><div class="tab-buttons"><button :class="{ active: activeTab === 'songs' }" @click="activeTab = 'songs'">Kho nhạc <b>{{ songsList.length }}</b></button><button :class="{ active: activeTab === 'users' }" @click="activeTab = 'users'">Tài khoản <b>{{ usersList.length }}</b></button></div></header>
    <div v-if="errorMsg" class="admin-alert">{{ errorMsg }}</div>
    <div v-if="activeTab === 'songs'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">IMPORT PIPELINE</span><h2>Thêm nhạc từ YouTube</h2></div><span class="status-dot">● ONLINE</span></div><DiscordBotSearch @song-added="refreshSongs" /><div class="panel-heading list-heading"><div><span class="panel-kicker">LIBRARY INDEX</span><h2>Danh sách nhạc hệ thống</h2></div><div class="panel-actions"><button class="refresh-btn" @click="restoreLegacy">↥ Khôi phục 188 bài</button><button class="refresh-btn" @click="refreshSongs">↻ Làm mới</button></div></div><div v-if="songsLoading" class="inline-state">Đang tải thư viện...</div><div v-else-if="!songsList.length" class="inline-state">Chưa có bài hát nào trong kho.</div><div v-else class="list-wrapper"><div v-for="song in songsList" :key="song.id" class="list-item"><div class="info"><img :src="song.cover || '/images/ChoCiu.jpg'" :alt="song.title" class="tiny-cover" /><div><strong>{{ song.title }}</strong><span>{{ song.artist || 'Unknown artist' }}</span><small class="media-key">{{ song.media_key || 'LEGACY / 188 GỐC' }}</small></div></div><div class="row-actions"><button @click="startEdit(song)" class="edit-btn">Sửa</button><button @click="handleDeleteSong(song.id)" class="delete-btn">Xóa</button></div></div></div></div>
    <div v-if="editingSong && activeTab === 'songs'" class="edit-song-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">METADATA EDITOR</span><h2>Chỉnh sửa bài hát</h2></div><button class="refresh-btn" type="button" @click="cancelEdit">Đóng</button></div><p class="edit-note">Bạn có thể đổi tên, ca sĩ, ảnh bìa hoặc lyrics. Link audio Cloudinary và mã bài vẫn được giữ nguyên.</p><form class="edit-song-form" @submit.prevent="saveSong"><label><span>TÊN BÀI HÁT</span><input v-model.trim="editMetadata.title" required maxlength="240" /></label><label><span>CA SĨ / NGHỆ SĨ</span><input v-model.trim="editMetadata.artist" required maxlength="160" /></label><label class="wide"><span>LYRICS</span><textarea v-model="editMetadata.lyrics" rows="5" maxlength="100000"></textarea></label><div class="form-actions"><button type="button" class="refresh-btn" @click="cancelEdit">Hủy</button><button type="submit" class="primary-btn" :disabled="isSongSaving">{{ isSongSaving ? 'Đang lưu...' : 'Lưu metadata' }}</button></div></form></div>
    <div v-else-if="activeTab !== 'songs'" class="admin-panel glass-panel"><div class="panel-heading"><div><span class="panel-kicker">ACCESS MANAGEMENT</span><h2>Cấp tài khoản mới</h2></div></div><form @submit.prevent="handleAddUser" class="add-user-form"><label><span>TÊN ĐĂNG NHẬP</span><input v-model.trim="newUser.username" placeholder="member.name" required minlength="2" /></label><label><span>MẬT KHẨU</span><input v-model="newUser.password" type="password" placeholder="Tối thiểu 8 ký tự" required minlength="8" /></label><label><span>VAI TRÒ</span><select v-model="newUser.role"><option value="user">Member</option><option value="admin">Admin</option></select></label><button type="submit" class="primary-btn" :disabled="isSubmitting">{{ isSubmitting ? 'Đang lưu...' : 'Cấp quyền →' }}</button></form><p v-if="userMsg" class="success-msg">{{ userMsg }}</p><div class="panel-heading list-heading"><div><span class="panel-kicker">MEMBERS DIRECTORY</span><h2>Danh sách tài khoản</h2></div><button class="refresh-btn" @click="refreshUsers">↻ Làm mới</button></div><div class="list-wrapper"><div v-for="user in usersList" :key="user.id" class="list-item"><div class="user-row"><div class="avatar">{{ user.username.slice(0,1).toUpperCase() }}</div><div><strong>{{ user.username }}</strong><span>{{ user.role === 'admin' ? 'Administrator' : 'Member' }}</span></div></div><button v-if="user.username !== 'admin'" @click="handleDeleteUser(user.id)" class="delete-btn">Thu hồi</button></div></div></div>
  </section>
</template>

<script setup>
import { onMounted, ref } from 'vue';
import DiscordBotSearch from '../components/DiscordBotSearch.vue';
import { getUsers, addUser, deleteUser, getSongs, deleteSong, updateSong, importLegacySongs } from '../services/api';
import { loadSongs } from '../data/songs';

const activeTab = ref('songs');
const songsList = ref([]); const usersList = ref([]); const userMsg = ref(''); const errorMsg = ref(''); const isSubmitting = ref(false); const songsLoading = ref(false);
const newUser = ref({ username: '', password: '', role: 'user' }); const editingSong = ref(null); const editMetadata = ref({ title: '', artist: '', cover: '', lyrics: '' }); const isSongSaving = ref(false);
const restoreLegacy = async () => { if (!window.confirm('Khôi phục toàn bộ 188 bài hát vào Supabase? Các URL đã tồn tại sẽ được bỏ qua.')) return; songsLoading.value = true; errorMsg.value = ''; try { const response = await importLegacySongs(); userMsg.value = response.message; await refreshSongs(); window.setTimeout(() => { userMsg.value = ''; }, 5000); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshSongs = async () => { songsLoading.value = true; errorMsg.value = ''; try { songsList.value = await getSongs(); await loadSongs(); } catch (error) { errorMsg.value = error.message; } finally { songsLoading.value = false; } };
const refreshUsers = async () => { errorMsg.value = ''; try { usersList.value = await getUsers(); } catch (error) { errorMsg.value = error.message; } };
const startEdit = (song) => { editingSong.value = song; editMetadata.value = { title: song.title || '', artist: song.artist || '', cover: song.cover || '', lyrics: song.lyrics || '' }; }; const cancelEdit = () => { editingSong.value = null; }; const saveSong = async () => { if (!editingSong.value) return; isSongSaving.value = true; errorMsg.value = ''; try { const response = await updateSong(editingSong.value.id, editMetadata.value); userMsg.value = response.message || 'Đã cập nhật metadata bài hát.'; cancelEdit(); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } finally { isSongSaving.value = false; } };
const handleDeleteSong = async (id) => { if (!window.confirm('Xóa bài hát này khỏi thư viện?')) return; try { await deleteSong(id); await refreshSongs(); } catch (error) { errorMsg.value = error.message; } };
const handleAddUser = async () => { isSubmitting.value = true; errorMsg.value = ''; try { const response = await addUser(newUser.value.username, newUser.value.password, newUser.value.role); if (!response.success) throw new Error(response.message); userMsg.value = response.message; newUser.value = { username: '', password: '', role: 'user' }; await refreshUsers(); window.setTimeout(() => { userMsg.value = ''; }, 3000); } catch (error) { errorMsg.value = error.message; } finally { isSubmitting.value = false; } };
const handleDeleteUser = async (id) => { if (!window.confirm('Thu hồi tài khoản này?')) return; try { await deleteUser(id); await refreshUsers(); } catch (error) { errorMsg.value = error.message; } };
onMounted(() => { refreshSongs(); refreshUsers(); });
</script>

<style scoped>
.admin-container { max-width: 1180px; margin: 0 auto; padding: 18px 0 60px; }.admin-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 25px; padding: 32px 0 34px; }.eyebrow, .panel-kicker { color: var(--gold); font: 9px var(--font-mono); letter-spacing: 1.8px; }.admin-header h1 { margin-top: 12px; font: 500 clamp(40px, 5vw, 62px)/.95 var(--font-display); letter-spacing: -2px; }.admin-header h1 em { color: var(--gold); font-style: italic; }.admin-header p:last-child { max-width: 520px; margin-top: 15px; color: var(--text-sub); font-size: 12px; line-height: 1.6; }.tab-buttons { display: flex; gap: 5px; padding: 5px; border: 1px solid var(--hairline-soft); border-radius: 12px; background: var(--glass); }.tab-buttons button { border: 0; border-radius: 8px; padding: 10px 12px; background: transparent; color: var(--text-faint); cursor: pointer; font-size: 10px; }.tab-buttons button.active { background: rgba(245,185,122,.13); color: var(--gold-bright); }.tab-buttons b { margin-left: 5px; color: var(--text-faint); font: 9px var(--font-mono); }.admin-alert { padding: 12px 14px; margin-bottom: 15px; border: 1px solid rgba(255,109,125,.3); border-radius: 10px; background: rgba(255,109,125,.08); color: var(--crimson); font-size: 11px; }.admin-panel { padding: clamp(18px, 3vw, 28px); border-radius: 18px; }.panel-heading { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 18px; }.panel-heading h2 { margin-top: 7px; color: var(--text-main); font: 500 23px var(--font-display); }.status-dot { color: var(--mint); font: 8px var(--font-mono); letter-spacing: 1px; }.list-heading { margin-top: 36px; padding-top: 28px; border-top: 1px solid var(--hairline-soft); }.panel-actions { display: flex; gap: 7px; }.refresh-btn { border: 1px solid var(--hairline); border-radius: 9px; padding: 8px 10px; background: transparent; color: var(--text-sub); cursor: pointer; font-size: 10px; }.refresh-btn:hover { border-color: rgba(245,185,122,.4); color: var(--gold); }.list-wrapper { display: flex; flex-direction: column; gap: 5px; }.list-item { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px; border: 1px solid transparent; border-radius: 11px; background: rgba(255,255,255,.025); }.list-item:hover { border-color: var(--hairline-soft); background: rgba(255,255,255,.045); }.info, .user-row { display: flex; align-items: center; gap: 11px; min-width: 0; }.info > div, .user-row > div:last-child { display: flex; flex-direction: column; min-width: 0; }.info strong, .user-row strong { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }.info span, .user-row span { margin-top: 4px; color: var(--text-sub); font-size: 9px; }.media-key { margin-top: 5px; color: var(--gold-dim) !important; font: 8px var(--font-mono) !important; }.tiny-cover { width: 42px; height: 42px; border-radius: 8px; object-fit: cover; }.avatar { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg, var(--violet), var(--gold)); color: #16121a; font: 800 11px var(--font-mono); }.row-actions { display:flex; align-items:center; gap:6px; }.edit-btn { border:1px solid rgba(245,185,122,.25); border-radius:8px; padding:7px 9px; background:transparent; color:var(--gold); cursor:pointer; font-size:10px; }.edit-btn:hover { background:rgba(245,185,122,.1); }.edit-song-panel { margin-bottom:15px; padding:clamp(18px,3vw,28px); border-radius:18px; }.edit-note { margin:-7px 0 16px; color:var(--text-sub); font-size:10px; }.edit-song-form { display:grid; grid-template-columns:1fr 1fr; gap:10px; }.edit-song-form label { display:grid; gap:7px; }.edit-song-form label span { color:var(--text-faint); font:8px var(--font-mono); letter-spacing:1px; }.edit-song-form input,.edit-song-form textarea { width:100%; box-sizing:border-box; padding:11px 12px; border:1px solid var(--hairline); border-radius:9px; outline:0; background:rgba(3,5,9,.35); color:var(--text-main); font-size:11px; }.edit-song-form .wide,.edit-song-form .form-actions { grid-column:1/-1; }.edit-song-form .form-actions { display:flex; justify-content:flex-end; gap:8px; }.delete-btn { border: 1px solid rgba(255,109,125,.22); border-radius: 8px; padding: 7px 9px; background: transparent; color: var(--crimson); cursor: pointer; font-size: 10px; }.delete-btn:hover { background: rgba(255,109,125,.1); }.inline-state { padding: 30px; color: var(--text-sub); text-align: center; font-size: 11px; }.add-user-form { display: grid; grid-template-columns: 1.1fr 1.1fr .7fr auto; align-items: end; gap: 10px; }.add-user-form label { display: grid; gap: 7px; }.add-user-form label span { color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1px; }.add-user-form input, .add-user-form select { min-width: 0; padding: 11px 12px; border: 1px solid var(--hairline); border-radius: 9px; outline: 0; background: rgba(3,5,9,.35); color: var(--text-main); font-size: 11px; }.add-user-form input:focus { border-color: var(--gold); }.primary-btn { border: 0; border-radius: 9px; padding: 11px 13px; background: var(--gold); color: #171218; cursor: pointer; font-size: 10px; font-weight: 800; white-space: nowrap; }.primary-btn:disabled { opacity: .5; cursor: progress; }.success-msg { margin-top: 12px; color: var(--mint); font-size: 10px; }@media (max-width: 760px) { .admin-header { align-items: flex-start; flex-direction: column; }.tab-buttons { align-self: stretch; }.tab-buttons button { flex: 1; }.add-user-form { grid-template-columns: 1fr; }.admin-container { padding-bottom: 95px; } }
</style>
